/* SHA-256 ringkas. Ditulis sendiri, bukan crypto.subtle, karena crypto.subtle
   tidak tersedia pada origin http:// biasa — persis kondisi bila berkas ini
   disajikan lewat jaringan kantor tanpa HTTPS. */
function sha256(pesan){
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const b=[]; for(const ch of unescape(encodeURIComponent(pesan))) b.push(ch.charCodeAt(0));
  const bitLen=b.length*8;
  b.push(0x80); while(b.length%64!==56) b.push(0);
  for(let i=7;i>=0;i--) b.push((bitLen/Math.pow(2,i*8))&0xff);
  const rr=(x,n)=>(x>>>n)|(x<<(32-n));
  for(let i=0;i<b.length;i+=64){
    const w=new Array(64);
    for(let t=0;t<16;t++) w[t]=(b[i+t*4]<<24)|(b[i+t*4+1]<<16)|(b[i+t*4+2]<<8)|b[i+t*4+3];
    for(let t=16;t<64;t++){
      const s0=rr(w[t-15],7)^rr(w[t-15],18)^(w[t-15]>>>3);
      const s1=rr(w[t-2],17)^rr(w[t-2],19)^(w[t-2]>>>10);
      w[t]=(w[t-16]+s0+w[t-7]+s1)|0;
    }
    let [a,c,d,e,f,g,h,l]=[H[0],H[1],H[2],H[3],H[4],H[5],H[6],H[7]];
    for(let t=0;t<64;t++){
      const S1=rr(f,6)^rr(f,11)^rr(f,25), ch=(f&g)^((~f)&h);
      const t1=(l+S1+ch+K[t]+w[t])|0;
      const S0=rr(a,2)^rr(a,13)^rr(a,22), mj=(a&c)^(a&d)^(c&d);
      const t2=(S0+mj)|0;
      l=h; h=g; g=f; f=(e+t1)|0; e=d; d=c; c=a; a=(t1+t2)|0;
    }
    H=[(H[0]+a)|0,(H[1]+c)|0,(H[2]+d)|0,(H[3]+e)|0,(H[4]+f)|0,(H[5]+g)|0,(H[6]+h)|0,(H[7]+l)|0];
  }
  return H.map(x=>((x>>>0).toString(16).padStart(8,'0'))).join('');
}

function cariAkun(id){
  const bersih = (id||'').trim().toUpperCase();
  const daftar = semuaAkun();
  return daftar.find(a => a.id.toUpperCase() === bersih)
      || daftar.find(a => a.id.replace(/^0+/,'') === bersih.replace(/^0+/,'') && /^\d+$/.test(bersih));
}

/* =======================================================================
   EAN-13
   Barcode sebelumnya hanya sembilan angka tanpa check digit, sehingga tidak
   pernah cocok bila dipindai dari barcode EAN-13 sungguhan. Di sini kodenya
   dibentuk lengkap 13 digit beserta check digit, dan sebagian digambar agar
   benar-benar dapat diuji pindai.
   Awalan 899 adalah awalan GS1 untuk Indonesia.
   ======================================================================= */
const EAN_L=['0001101','0011001','0010011','0111101','0100011','0110001','0101111','0111011','0110111','0001011'];
const EAN_G=['0100111','0110011','0011011','0100001','0011101','0111001','0000101','0010001','0001001','0010111'];
const EAN_R=['1110010','1100110','1101100','1000010','1011100','1001110','1010000','1000100','1001000','1110100'];
const EAN_P=['LLLLLL','LLGLGG','LLGGLG','LLGGGL','LGLLGG','LGGLLG','LGGGLL','LGLGLG','LGLGGL','LGGLGL'];

function ean13Check(d12){
  let s = 0;
  for(let i=0;i<12;i++) s += (+d12[i]) * (i % 2 ? 3 : 1);
  return String((10 - s % 10) % 10);
}
const ean13Lengkap = d12 => d12 + ean13Check(d12);

/* Susunan EAN-13: pengawal 101, enam digit kiri, pemisah tengah 01010,
   enam digit kanan, penutup 101. Digit pertama tidak digambar sebagai batang
   melainkan menentukan pola ganjil-genap keenam digit kiri. */
function ean13Modul(kode){
  const p = EAN_P[+kode[0]];
  let m = '101';
  for(let i=1;i<=6;i++) m += (p[i-1]==='L' ? EAN_L : EAN_G)[+kode[i]];
  m += '01010';
  for(let i=7;i<=12;i++) m += EAN_R[+kode[i]];
  return m + '101';
}

/* Digambar sebagai SVG supaya tajam pada layar maupun saat dicetak.
   Zona sunyi di kiri dan kanan ikut disediakan karena tanpa itu banyak
   pemindai gagal mengunci kode. */
function svgEan13(kode, tinggiBatang){
  const mod = ean13Modul(kode), n = mod.length;
  const sunyi = 9, tinggi = tinggiBatang || 62, lebih = 9;   // batang pengawal lebih panjang
  const total = n + sunyi*2;
  const panjangBatang = i => (i<3 || (i>=45 && i<50) || i>=92) ? tinggi + lebih : tinggi;
  let batang = '';
  for(let i=0;i<n;i++){
    if(mod[i] === '1')
      batang += `<rect x="${sunyi+i}" y="0" width="1" height="${panjangBatang(i)}" fill="#000"/>`;
  }
  const teks = (x,t,anchor) =>
    `<text x="${x}" y="${tinggi+lebih+9}" font-size="9" font-family="monospace"
      text-anchor="${anchor}" fill="#000">${t}</text>`;
  return `<svg viewBox="0 0 ${total} ${tinggi+lebih+12}" width="100%"
      preserveAspectRatio="xMidYMid meet" shape-rendering="crispEdges"
      role="img" aria-label="Barcode EAN-13 ${kode}">
    <rect width="${total}" height="${tinggi+lebih+12}" fill="#fff"/>
    ${batang}
    ${teks(sunyi-2, kode[0], 'end')}
    ${teks(sunyi+3+21, kode.slice(1,7), 'middle')}
    ${teks(sunyi+50+21, kode.slice(7), 'middle')}
  </svg>`;
}

