/* --------------------------- aturan analitis --------------------------- */

/* Selisih satu SKU.
   Barang yang sudah diterima fisik tetapi GR belum diproses membuat stok
   sistem tercatat LEBIH RENDAH dari fisik, sehingga menghasilkan selisih
   PLUS - bukan minus. Qty itu dikeluarkan agar tidak ditelusuri percuma. */
/* Sejak stok dipasok dari dokumen audit yang sudah tervalidasi, tidak ada lagi
   kolom GR tertunda. Selisih dihitung langsung terhadap stok akhir dokumen. */
function hitungSelisih(fisik, sistem){
  const selisih = +(fisik - sistem).toFixed(4);
  return {
    kotor: selisih, bersih: selisih,
    arah: selisih > 0 ? 'PLUS' : selisih < 0 ? 'MINUS' : 'COCOK'
  };
}

/* Outstanding selalu memakai tiga komponen. Uang Plus dan Nominal Minus Asset
   tidak pernah di-netting di data sumber; ketiganya hanya bertemu di sini. */
function outstanding(nma, uangPlus, payment){
  return +(nma - uangPlus - payment).toFixed(2);
}

function klasifikasi(nilai){
  const n = Math.abs(nilai);
  if(n <= AMBANG.minor) return 'MINOR';
  if(n <= AMBANG.major) return 'MAJOR';
  return 'CRITICAL';
}

function barisHasil(){
  const out = [];
  state.hitung.forEach((fisik, sku)=>{
    const p = KAT().find(m=>m.sku===sku);
    const v = snap(sku);
    const s = hitungSelisih(fisik, v.sistem);
    out.push({p, fisik, ...s, sistem:v.sistem, nilai: s.bersih * p.hpp});
  });
  // Selalu diurutkan menurut nilai Rupiah, bukan jumlah item.
  return out.sort((a,b)=>Math.abs(b.nilai)-Math.abs(a.nilai));
}

