/* =======================================================================
   PENGELOLAAN AKUN

   AKUN di atas adalah daftar bawaan yang tertanam di berkas. Akun yang
   ditambahkan Administrator, perubahan sandi, dan penonaktifan disimpan
   terpisah di perangkat lalu ditimpakan di atas daftar bawaan, sehingga
   daftar bawaan tidak pernah berubah dan selalu bisa dijadikan acuan.
   ======================================================================= */
const KUNCI_AKUN = 'audit-scanner-akun-v1';
const bacaAkunLokal  = () => { try{ return JSON.parse(localStorage.getItem(KUNCI_AKUN)||'{}'); }catch(e){ return {}; } };
const tulisAkunLokal = o => { try{ localStorage.setItem(KUNCI_AKUN, JSON.stringify(o)); }catch(e){ toast('Penyimpanan perangkat penuh'); } };

/* Daftar akun sesungguhnya: bawaan, ditimpa perubahan lokal, ditambah akun baru. */
function semuaAkun(){
  const lokal = bacaAkunLokal();
  const hasil = AKUN.map(a => ({...a, ...(lokal.ubah?.[a.id] || {})}));
  (lokal.baru || []).forEach(a => hasil.push({...a, ...(lokal.ubah?.[a.id] || {})}));
  return hasil;
}
function simpanPerubahanAkun(id, data){
  const l = bacaAkunLokal();
  l.ubah ||= {}; l.ubah[id] = {...(l.ubah[id]||{}), ...data};
  tulisAkunLokal(l);
  antrekan('akun', 'akun', l);
}
function tambahAkunBaru(a){
  const l = bacaAkunLokal();
  l.baru ||= []; l.baru.push(a);
  tulisAkunLokal(l);
  antrekan('akun', 'akun', l);
}
