function terapkanUnggah(){
  const h = state.unggahHasil, j = JENIS_UNGGAH[h.jenis];
  const a = j.baca().concat(h.terima);
  tulisKe(j.kunci, a);
  /* Dikirim utuh, bukan per baris. Riwayat ini diunggah sebagai satu berkas
     dan dipakai sebagai satu kesatuan; menggabungkan per baris di perangkat
     lain akan menghasilkan campuran dua versi berkas tanpa ada yang tahu
     versi mana yang sedang dilihat. */
  antrekan('riwayatData', h.jenis, {jenis:h.jenis, isi:a, diubah:new Date().toISOString()});
  $('unSheet').classList.remove('show');
  renderUnggahan(); toast(h.terima.length + ' baris tersimpan');
}

function kosongkanUnggahan(jenis){
  const j = JENIS_UNGGAH[jenis];
  if(!j.baca().length) return toast('Belum ada data');
  tulisKe(j.kunci, []);
  antrekan('riwayatData', jenis, {jenis, isi:[], diubah:new Date().toISOString()});
  renderUnggahan(); toast(j.nama + ' dikosongkan');
}

