/* --------------------------- prioritas audit --------------------------- */
/* Bobot berikut menentukan urutan outlet yang perlu didahulukan. Angkanya
   masih menunggu keputusan manajemen [MK]; yang penting susunannya jelas,
   bukan tersembunyi di dalam rumus. */
const BOBOT = {temuanPerJuta:1, cmsRingan:2, cmsSedang:5, cmsBerat:12, voidPerJuta:1.5};

function skorPrioritas(){
  const skor = {};
  const tambah = (o,n,sebab) => {
    const x = skor[o] ||= {outlet:o, skor:0, sebab:[]};
    x.skor += n; if(sebab) x.sebab.push(sebab);
  };
  const temuan = {};
  semuaTemuan().forEach(t => temuan[t.outlet] = (temuan[t.outlet]||0) + t.nilai);
  Object.entries(temuan).forEach(([o,n]) =>
    tambah(o, n/1e6*BOBOT.temuanPerJuta, `temuan ${rp(n)}`));

  const cms = {};
  bacaCms().forEach(c=>{
    const b = c.tingkat==='BERAT'?BOBOT.cmsBerat : c.tingkat==='SEDANG'?BOBOT.cmsSedang : BOBOT.cmsRingan;
    tambah(c.outlet, b);
    cms[c.outlet] = (cms[c.outlet]||0)+1;
  });
  Object.entries(cms).forEach(([o,n]) => { skor[o].sebab.push(`${n} pelanggaran CMS`); });

  const vd = {};
  bacaVoid().forEach(v => vd[v.outlet] = (vd[v.outlet]||0) + v.nilai);
  Object.entries(vd).forEach(([o,n]) =>
    tambah(o, n/1e6*BOBOT.voidPerJuta, `void ${rp(n)}`));

  return Object.values(skor).sort((a,b)=>b.skor-a.skor);
}

function renderPrioritas(){
  const p = skorPrioritas();
  $('prRingkas').innerHTML = `
    <div class="notice info">Urutan disusun dari riwayat temuan, pelanggaran CMS/CCTV, dan
      nilai void. Pelanggaran berat berbobot paling besar karena menyangkut kepatuhan,
      bukan sekadar selisih angka. Bobotnya masih menunggu keputusan manajemen [MK].</div>`;
  $('prJml').textContent = p.length + ' outlet';
  $('prList').innerHTML = p.length ? p.slice(0,25).map((x,i)=>`
    <div class="item" onclick="bukaRiwayatOutlet(${JSON.stringify(x.outlet).replace(/"/g,'&quot;')})">
      <div class="row">
        <div style="min-width:0"><div class="name">${i+1}. ${esc(x.outlet)}</div>
          <div class="sub">${esc(x.sebab.join(' · ')) || 'tanpa catatan'}</div></div>
        <span class="badge ${x.skor>=12?'b-red':x.skor>=5?'b-orange':'b-grey'}">${x.skor.toFixed(1)}</span>
      </div></div>`).join('')
    : `<div class="card center" style="color:var(--muted);font-size:12px;padding:22px">
        Belum ada data. Unggah riwayat temuan, CMS/CCTV, atau void lebih dulu.</div>`;
}

