/* Bawaannya gelap. Pilihan pengguna disimpan per perangkat, karena terang
   atau gelap tergantung tempat kerjanya: gudang belakang atau area terbuka. */
const KUNCI_TEMA = 'audit-scanner-tema-v1';
function terapkanTema(t){
  if(t === 'terang') document.documentElement.setAttribute('data-tema','terang');
  else document.documentElement.removeAttribute('data-tema');
  const m = document.querySelector('meta[name=theme-color]');
  if(m) m.setAttribute('content', t === 'terang' ? '#7f1324' : '#121014');
  const sub = $('menuTemaSub');
  if(sub) sub.textContent = t === 'terang' ? 'Terang' : 'Gelap';
}
function temaSekarang(){
  try{ return localStorage.getItem(KUNCI_TEMA) || 'gelap'; }catch(e){ return 'gelap'; }
}
function gantiTema(){
  const baru = temaSekarang() === 'gelap' ? 'terang' : 'gelap';
  try{ localStorage.setItem(KUNCI_TEMA, baru); }catch(e){}
  terapkanTema(baru);
  toast('Tema ' + (baru === 'terang' ? 'terang' : 'gelap') + ' dipakai');
}
terapkanTema(temaSekarang());

