function galatMasuk(pesan){
  $('loginGalat').textContent = pesan;
  $('loginPass').value = '';
  $('loginPass').focus();
}

function login(){
  const nik = $('loginId').value.trim();
  const sandi = $('loginPass').value;
  if(!nik || !sandi){ galatMasuk('Isi NIK dan kata sandi.'); return; }

  const akun = cariAkun(nik);
  // Pesan sengaja sama untuk ID salah maupun sandi salah, agar tidak
  // membocorkan NIK mana yang terdaftar.
  if(!akun || sha256(SALT_SANDI + sandi) !== akun.hash){
    galatMasuk('NIK atau kata sandi tidak cocok.'); return;
  }
  if(akun.peran === 'nonaktif'){
    /* Sandinya memang benar, jadi pesannya jangan menyiratkan salah ketik —
       orangnya akan mencoba terus. Yang perlu diketahui: akunnya dimatikan,
       dan siapa yang dapat menghidupkannya kembali. */
    galatMasuk('Akun ini dinonaktifkan dan tidak dapat dipakai masuk. '
             + 'Hubungi Administrator bila seharusnya masih aktif.'); return;
  }
  $('loginGalat').textContent = '';
  /* Sandi bawaan dihitung sebagai "wajib diganti" selama memang masih
     bawaan, bukan hanya sekali saat akun dibuat. Sandi 12345678 yang sama
     untuk seluruh tim dan tertulis di dalam berkas sama saja dengan tanpa
     sandi; yang membedakan hanyalah apakah orangnya sudah mengganti.
     Lembar ganti sandi ditawarkan, tidak memaksa — memaksa berarti tim
     tidak bisa langsung mencoba, dan itu yang Anda minta. */
  state.wajibGantiSandi = !!akun.sementara || pakaiSandiBawaan(akun);
  const padded = akun.nik;
  state.peran = akun.peran;
  state.hak = hakAkun(akun);
  muatStoreTambahan();
  state.tim = bangunTim();
  /* Jadwal tidak lagi dibangkitkan sendiri. Penugasan hanya berasal dari
     berkas jadwal yang diunggah Head, supaya yang tampil benar-benar
     jadwal yang disepakati, bukan sebaran contoh. */
  state.penugasan = bacaPenugasan();

  if(state.peran==='head'){
    /* Identitas diambil dari akun yang benar-benar masuk, bukan dari Head
       pertama pada daftar. Kalau diambil dari daftar, Head kedua akan
       menandatangani berita acara dengan nama Head pertama. */
    state.auditor = {nik:akun.id, nama:akun.nama, jabatan:akun.jabatan};
    state.jtTgl = hariIni();
    PROFIL.nama = akun.nama; PROFIL.nik = akun.nik || akun.id;
    PROFIL.kode = akun.nik && akun.nik !== '-' ? kode5(akun.nik) : '-';
    isiPilihanOutlet();
  }else if(['admin','administrator','manager'].includes(state.peran)){
    // Administrator dan Admin tidak termasuk daftar auditor lapangan, jadi
    // identitasnya diambil langsung dari akun agar tidak jatuh ke auditor
    // pertama — yang membuat avatar dan nama di berita acara ikut keliru.
    state.auditor = {nik:akun.id, nama:akun.nama, jabatan:akun.jabatan};
    PROFIL.nama = akun.nama; PROFIL.nik = akun.nik || akun.id;
    PROFIL.kode = akun.nik && akun.nik !== '-' ? kode5(akun.nik) : '-';
    isiPilihanOutlet();
  }else{
    /* Cadangannya akun yang masuk itu sendiri, bukan anggota tim pertama.
       Auditor yang belum kebagian outlet akan terbaca sebagai orang lain
       kalau jatuh ke state.tim[0] — nama itu ikut ke berita acara. */
    const me = state.tim.find(a=>a.nik===padded) || {
      nik: akun.id, nama: akun.nama, jabatan: akun.jabatan,
      kode: akun.nik && akun.nik !== '-' ? kode5(akun.nik) : '-',
      region: '—', outlet: []
    };
    state.auditor = {nik:me.nik, nama:me.nama, jabatan:me.jabatan};
    PROFIL.nik = me.nik; PROFIL.kode = me.kode; PROFIL.nama = me.nama;
    PROFIL.jabatan = me.jabatan; PROFIL.area = 'Region utama '+me.region;
    PROFIL.outlet = me.outlet;
    isiPilihanOutlet();
  }
  $('loginScreen').style.display='none';
  $('mainApp').style.display='block';
  $('heroName').textContent = state.auditor.nama.split(' ')[0];
  $('setupAuditor').textContent = state.auditor.nama;
  $('signAuditorName').textContent = state.auditor.nama + ' · ' + nik;
  $('avatar').textContent = state.auditor.nama.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
  $('clock').textContent = jam();
  updateNet();
  mulaiSinkronBerkala();
  if(state.peran==='administrator'){
    $('topEyebrow').textContent = 'Administrator';
    renderAkun(); showScreen('akun');
    toast('Masuk sebagai Administrator');
    if(state.wajibGantiSandi) setTimeout(bukaGantiSandi, 600);
  }else if(state.peran==='admin'){
    $('topEyebrow').textContent = 'Admin Internal Auditor';
    renderDokumen();
    showScreen('dokumen');
    toast('Masuk sebagai Admin Internal Auditor');
    if(state.wajibGantiSandi) setTimeout(bukaGantiSandi, 600);
  }else if(state.peran==='manager'){
    $('topEyebrow').textContent = 'Manager Internal Audit';
    renderHeadDash(); showScreen('headDash');
    toast('Masuk sebagai Manager Internal Audit');
    if(state.wajibGantiSandi) setTimeout(bukaGantiSandi, 600);
  }else if(state.peran==='head'){
    $('topEyebrow').textContent = 'Head Internal Auditor';
    renderHeadDash(); renderPenempatan(); renderJadwalTim(); renderKpi();
    showScreen('headDash');
    toast('Masuk sebagai Head Internal Auditor');
    if(state.wajibGantiSandi) setTimeout(bukaGantiSandi, 600);
  }else{
    $('topEyebrow').textContent = 'Internal Audit';
    renderChecklist(); renderJadwal(); renderProfil(); renderDashToday();
    showScreen('dashboard');
    toast('Masuk berhasil — Audit Scanner aktif');
    if(state.wajibGantiSandi) setTimeout(bukaGantiSandi, 600);
    const d = bacaDraft();
    if(d && d.nik === state.auditor.nik) setTimeout(()=>tawarkanDraft(d), 700);
  }
}

/* --------------------------- navigasi --------------------------- */
/* Layar penghitungan hanya dapat dibuka selama sesi berjalan. Setelah sesi
   ditandatangani, satu-satunya jalur yang tersisa adalah melihat hasil di
   arsip, sehingga angka yang sudah dikunci tidak dapat disentuh lagi. */
const LAYAR_SESI = ['scanner','checklist','review','finding','capa'];

/* Hak yang diperlukan tiap layar. Penjagaan ditaruh di sini, bukan hanya di
   tombolnya, supaya layar tetap tertutup walau dipanggil dari jalan lain. */
const HAK_LAYAR = {penempatan:'jadwalUbah', jadwalTim:'jadwalUbah', kpi:'kpi',
                   /* Ringkasan Tim memuat cakupan dan KPI seluruh auditor.
                      Itu bahan Head dan Manager, bukan bahan rekan setim. */
                   headDash:'hasil',
                   dokumen:'dokumen', hpp:'hpp', unggahan:'unggahan', store:'store',
                   grafik:'grafik', prioritas:'grafik', audit:'audit',
                   akun:'akun', permintaan:'sandi', barcode:'barcode',
                   /* Pengaturan memuat kunci API Gemini, jadi hanya Administrator.
                      Perangkat disiapkan sekali sebelum diserahkan ke auditor, dan
                      sumber foto bawaan 'foto/' sudah benar untuk paket aplikasi
                      sehingga auditor tidak pernah perlu menyentuh layar ini. */
                   setelan:'akun'};

function showScreen(id){
  if(HAK_LAYAR[id] && !boleh(HAK_LAYAR[id])){
    toast('Akun Anda tidak punya hak akses untuk layar itu');
    return;
  }
  if(LAYAR_SESI.includes(id) && !state.sesiAktif){
    toast('Sesi sudah ditutup dan terkunci. Hasilnya dapat dilihat di Arsip Audit.');
    id = 'arsip';
  }
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  const el=$(id); if(el) el.classList.add('active');
  const judul={dashboard:'Dashboard',audit:'Setup Audit',scanner:'Menghitung',checklist:'Checklist',
               review:'Rekap Audit',finding:'Temuan',capa:'Berita Acara',done:'Sesi Dikunci',
               jadwal:'Jadwal Audit',profil:'Profil Saya',
               arsip:'Arsip Audit',hasil:'Hasil Audit',dokumen:'Dokumen Stock Audit',hpp:'Master HPP',
               akun:'Kelola Akun',permintaan:'Permintaan Sandi',store:'Daftar Store',barcode:'Barcode Produk',
               setelan:'Pengaturan',
               grafik:'Grafik Temuan',unggahan:'Unggahan Data',prioritas:'Prioritas Audit',
               headDash:'Ringkasan Tim',penempatan:'Penempatan Auditor',
               jadwalTim:'Jadwal Tim',kpi:'Penilaian KPI'};
  $('topTitle').textContent = judul[id]||'Audit Scanner';
  renderNav(id);
  if(id==='review') renderReview();
  if(id==='scanner'){ renderItemList(); tandaiDraft(); tandaiSinkron();
    /* Kamera langsung tidak lagi dibuka sendiri. Di dalam bingkai claude.ai
       permintaannya hampir selalu ditolak, dan pesan galat yang muncul tiap
       kali layar ini dibuka hanya menakuti auditor atas hal yang bukan
       kesalahannya. Jalur utama sekarang Foto Barcode, yang tidak butuh izin
       bingkai; kamera langsung tinggal satu ketukan bila perangkatnya mampu. */ }
  if(id==='checklist') renderChecklist();
  if(id==='finding') renderFindings();
  if(id==='capa') renderCapa();
  if(id==='jadwal') renderJadwal();
  if(id==='profil') renderProfil();
  if(id==='dashboard') renderDashToday();
  if(id==='arsip') renderArsip();
  if(id==='dokumen') renderDokumen();
  if(id==='hpp') renderHpp();
  if(id==='akun') renderAkun();
  if(id==='setelan') renderSetelan();
  if(id==='permintaan') renderPermintaan();
  if(id==='store') renderStore();
  if(id==='barcode') renderBarcode();
  if(id==='grafik') renderGrafik();
  if(id==='unggahan') renderUnggahan();
  if(id==='prioritas') renderPrioritas();
  if(id==='headDash') renderHeadDash();
  if(id==='penempatan') renderPenempatan();
  if(id==='jadwalTim') renderJadwalTim();
  if(id==='kpi') renderKpi();
  if(id!=='scanner') stopCamera();
  window.scrollTo({top:0,behavior:'smooth'});
}
/* Katalog yang dihitung: dari dokumen aktif store itu bila ada. Bila tidak,
   audit tidak dapat dimulai, karena tanpa dokumen tidak ada stok pembanding. */
function katalogDariDokumen(d){
  return d.item.map((it,i)=>({
    sku: 'DOK-' + String(i+1).padStart(4,'0'),
    barcode: '', nama: it.nama, satuan: it.uom, kategori: '',
    hpp: hppUntuk(it.nama, it.hpp), sistem: it.akhir, awal: it.awal, masuk: it.masuk, keluar: it.keluar
  }));
}

/* =======================================================================
   PENGOSONGAN DATA

   Dipakai saat berpindah dari uji coba ke pemakaian sungguhan. Tiap
   kelompok dapat dipilih sendiri karena tidak semuanya perlu dibuang
   bersamaan: jadwal boleh diganti tanpa menghapus riwayat, dan hasil uji
   coba boleh dihapus tanpa kehilangan master akun atau store.
   ======================================================================= */
/* Dibungkus fungsi, bukan konstanta. Sebagai konstanta, daftar ini dinilai
   saat skrip dimuat dan menyebut kunci penyimpanan yang baru dideklarasikan
   di bawahnya, sehingga skrip berhenti di tengah dan seluruh deklarasi
   sesudahnya tidak pernah terisi. */
const kelompokData = () => [
  {kode:'arsip',    nama:'Hasil audit tersimpan', ket:'Sesi yang sudah dikunci beserta temuan dan tanda tangan',
   kunci:[KUNCI_ARSIP],     hitung:()=>bacaArsip().length + ' sesi'},
  {kode:'penugasan',nama:'Jadwal audit',          ket:'Seluruh penugasan dan jejak penjadwalan ulang',
   kunci:[KUNCI_PENUGASAN], hitung:()=>bacaPenugasan().length + ' penugasan'},
  {kode:'draft',    nama:'Draft sesi berjalan',   ket:'Hitungan yang belum dikunci di perangkat ini',
   kunci:[KUNCI_DRAFT],     hitung:()=>bacaDraft() ? '1 draft' : 'kosong'},
  {kode:'riwayat',  nama:'Riwayat temuan unggahan', ket:'Berkas riwayat temuan yang diunggah Admin',
   kunci:[KUNCI_RIWAYAT],   hitung:()=>bacaRiwayat().length + ' baris'},
  {kode:'cms',      nama:'Pelanggaran CMS/CCTV',  ket:'Berkas pelanggaran yang diunggah Admin',
   kunci:[KUNCI_CMS],       hitung:()=>bacaCms().length + ' baris'},
  {kode:'void',     nama:'Riwayat void',          ket:'Berkas transaksi void yang diunggah Admin',
   kunci:[KUNCI_VOID],      hitung:()=>bacaVoid().length + ' baris'},
  {kode:'dokumen',  nama:'Dokumen stok',          ket:'Dokumen stock audit beserta katalog SKU-nya',
   kunci:[KUNCI_DOK],       hitung:()=>bacaDokumen().length + ' dokumen'},
  {kode:'hpp',      nama:'Master HPP',          ket:'HPP yang diimpor atau dipanen dari dokumen',
   kunci:[KUNCI_HPP],       hitung:()=>Object.keys(bacaHpp()).length + ' produk'},
  {kode:'catatan',  nama:'Catatan outlet',        ket:'Catatan yang ditulis sebelum audit dimulai',
   kunci:[KUNCI_CATATAN],   hitung:()=>Object.keys(bacaCatatan()).length + ' catatan'},
  /* Akun yang dibuat di perangkat ini. Diperlukan karena daftar bawaan di
     berkas tinggal satu Administrator: tanpa kelompok ini, akun uji coba yang
     pernah dibuat di HP ini tetap ada dan terbaca sebagai akun resmi. */
  {kode:'akunLokal',nama:'Akun yang dibuat di perangkat ini', ket:'Akun tambahan dan perubahan peran. Administrator bawaan tidak terhapus',
   kunci:[KUNCI_AKUN, KUNCI_PERMINTAAN],
   hitung:()=>Math.max(0, semuaAkun().length - 1) + ' akun tambahan'},
  {kode:'lokasi',   nama:'Perubahan daftar lokasi', ket:'Store dan gudang yang ditambah, diubah, atau dihapus di perangkat ini',
   kunci:[KUNCI_STORE, KUNCI_STATUS, KUNCI_UBAH_LOKASI, KUNCI_HAPUS_LOKASI],
   hitung:()=>bacaStoreTambahan().length + ' lokasi tambahan'},
  {kode:'setelan',  nama:'Pengaturan perangkat',   ket:'Sumber foto produk, kunci API Gemini, dan alamat cloud',
   kunci:[KUNCI_FOTO_SUMBER, KUNCI_GEMINI, KUNCI_CLOUD],
   hitung:()=>(geminiSiap() ? 'kunci terpasang' : 'kunci kosong') + (cloudSiap() ? ' · cloud aktif' : '')},
  {kode:'antre',    nama:'Antrean kiriman cloud',  ket:'Perubahan yang belum sempat terkirim. Membuangnya berarti perubahan itu tidak akan pernah sampai ke perangkat lain',
   kunci:[KUNCI_ANTRE, KUNCI_TARIK],
   hitung:()=>bacaAntre().length + ' menunggu'}
];

function bukaResetData(){
  if(!bolehKelolaAkun()) return;
  state.resetPilih = [];
  gambarResetData();
  $('rdSheet').classList.add('show');
}

function gambarResetData(){
  $('rdIsi').innerHTML = `
    <div class="handle"></div>
    <h3>Kosongkan Data</h3>
    <p class="note">Pilih yang ingin dibuang. Akun, hak akses, dan daftar store
      tidak ikut terhapus.</p>
    <div>${kelompokData().map(k=>{
      const pilih = state.resetPilih.includes(k.kode);
      return `<button class="ol-row ${pilih?'mine':''}" onclick="togelReset('${k.kode}')">
        <span class="ol-box">${pilih?'✓':''}</span>
        <span style="flex:1;min-width:0"><span class="name">${esc(k.nama)}</span>
        <span class="sub">${esc(k.ket)} · <b>${esc(k.hitung())}</b></span></span>
      </button>`;
    }).join('')}</div>
    <div class="notice gr" style="margin-top:12px">Penghapusan tidak dapat dibatalkan dan
      hanya berlaku di perangkat ini. Unduh dulu yang masih diperlukan.</div>
    <div style="display:grid;grid-template-columns:1fr 1.3fr;gap:9px;margin-top:14px">
      <button class="btn ghost" onclick="$('rdSheet').classList.remove('show')">Batal</button>
      <button class="btn" style="background:var(--red);color:#fff" onclick="tanyaResetData()"
              ${state.resetPilih.length?'':'disabled'}>Kosongkan ${state.resetPilih.length||''}</button>
    </div>`;
}

function togelReset(k){
  const i = state.resetPilih.indexOf(k);
  if(i>=0) state.resetPilih.splice(i,1); else state.resetPilih.push(k);
  gambarResetData();
}

function tanyaResetData(){
  const pilih = kelompokData().filter(k=>state.resetPilih.includes(k.kode));
  $('rdIsi').innerHTML = `
    <div class="handle"></div>
    <h3>Kosongkan Sekarang?</h3>
    <div class="card" style="box-shadow:none">
      ${pilih.map(k=>`<div class="kpi"><div class="left">${esc(k.nama)}</div>
        <div class="right v-minus">${esc(k.hitung())}</div></div>`).join('')}
    </div>
    <div class="notice gr" style="border-left-color:var(--red);margin-top:12px">
      Tidak dapat dibatalkan.</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:16px">
      <button class="btn ghost" onclick="gambarResetData()">Tidak</button>
      <button class="btn" style="background:var(--red);color:#fff" onclick="jalankanResetData()">Ya, Kosongkan</button>
    </div>`;
}

function jalankanResetData(){
  const pilih = kelompokData().filter(k=>state.resetPilih.includes(k.kode));
  pilih.forEach(k=>k.kunci.forEach(x=>{ try{ localStorage.removeItem(x); }catch(e){} }));
  if(pilih.some(k=>k.kunci.includes(KUNCI_DOK))) tulisDokumen([]);   // IndexedDB ikut dikosongkan
  if(state.resetPilih.includes('penugasan')) state.penugasan = [];
  const perluMuatUlang = state.resetPilih.includes('akunLokal')
                      || state.resetPilih.includes('lokasi');
  state.resetPilih = [];
  $('rdSheet').classList.remove('show');
  state.tim.forEach(a=>a.realisasi=null);
  renderAkun();
  /* Identitas yang masuk, daftar tim, dan daftar lokasi semuanya diturunkan
     dari data yang baru saja dihapus. Tanpa muat ulang, layar masih memakai
     turunan lama dan menampilkan akun atau outlet yang sudah tidak ada. */
  if(perluMuatUlang){
    toast('Data dikosongkan. Aplikasi dimuat ulang…');
    setTimeout(()=>location.reload(), 900);
    return;
  }
  toast('Data dikosongkan');
}

/* --------------------------- riwayat sebelum menghitung --------------------------- */
/* Auditor melihat riwayat outlet sebelum sesi dibuka. Temuan yang berulang di
   outlet yang sama biasanya baru terlihat bila riwayatnya dibaca lebih dulu,
   bukan setelah penghitungan selesai. */
const KUNCI_CATATAN = 'audit-scanner-catatan-outlet-v1';
const bacaCatatan  = () => { try{ return JSON.parse(localStorage.getItem(KUNCI_CATATAN)||'{}'); }catch(e){ return {}; } };
const tulisCatatan = o => { try{ localStorage.setItem(KUNCI_CATATAN, JSON.stringify(o)); }catch(e){} };

function bukaRiwayatSebelumAudit(){
  const outlet = $('outletSelect').value;
  if(!outlet) return;
  state.petaAudit = petaAuditTerakhir();
  const a = auditTerakhir(outlet);
  const temuan = semuaTemuan().filter(t=>normalNama(t.outlet)===normalNama(outlet))
    .sort((x,y)=>y.tanggal.localeCompare(x.tanggal));
  const sesi = bacaArsip().filter(r=>normalNama(r.outlet)===normalNama(outlet))
    .sort((x,y)=>y.ditutup.localeCompare(x.ditutup));
  const cms = bacaCms().filter(c=>normalNama(c.outlet)===normalNama(outlet));
  const vd  = bacaVoid().filter(v=>normalNama(v.outlet)===normalNama(outlet));
  const jml = k => temuan.reduce((t,x)=>t+(x[k]||0),0);
  const belumLunas = temuan.filter(t=>t.nilai > 0);
  const catatan = bacaCatatan()[normalNama(outlet)] || {};

  /* Jenis temuan yang paling sering berulang di outlet ini, supaya auditor
     tahu apa yang perlu diperiksa lebih teliti sejak awal. */
  const perJenis = {};
  temuan.forEach(t=> perJenis[t.jenis] = (perJenis[t.jenis]||0)+1);
  const berulang = Object.entries(perJenis).filter(([,n])=>n>1)
    .sort((x,y)=>y[1]-x[1]).slice(0,4);

  $('rsIsi').innerHTML = `
    <div class="handle"></div>
    <h3>Riwayat ${esc(outlet)}</h3>
    <p class="note">${a ? `Terakhir diaudit ${a.umur} hari lalu, ${esc(a.tanggal)}.`
                        : 'Belum pernah tercatat diaudit.'}</p>
    ${a && a.umur < JEDA_MIN ? `<div class="notice gr">Baru ${a.umur} hari sejak audit
      terakhir, di bawah jeda ${JEDA_MIN} hari. Pastikan ini memang kunjungan ulang
      yang disengaja.</div>` : ''}
    <!-- Isi laporan sebelumnya (nominal, uraian temuan, outstanding) sengaja
         tidak ditampilkan di sini. Auditor yang membaca angka hasil audit lalu
         cenderung menghitung ke arah angka itu; yang perlu ia tahu sebelum
         menghitung hanyalah kapan outlet ini terakhir dikunjungi, berapa kali,
         dan jenis temuan apa yang berulang. Isi laporannya tetap tersedia bagi
         Head dan Admin di Arsip Audit. -->
    <div class="split">
      <div class="box"><div class="lab">Sesi audit</div><div class="num">${sesi.length}</div></div>
      <div class="box"><div class="lab">Temuan tercatat</div><div class="num">${temuan.length}</div></div>
      <div class="box"><div class="lab">Pelanggaran CMS</div><div class="num" style="color:var(--orange)">${cms.length}</div></div>
      <div class="box"><div class="lab">Transaksi void</div><div class="num">${vd.length}</div></div>
    </div>

    ${berulang.length ? `<div class="notice info" style="margin-top:12px">
      <b>Yang berulang di outlet ini:</b> ${berulang.map(([j,n])=>`${esc(j)} ${n}×`).join(' · ')}.
      Periksa bagian itu lebih dulu.</div>` : ''}
    ${belumLunas.length ? `<div class="notice gr" style="margin-top:10px">
      ${belumLunas.length} temuan sebelumnya masih terbuka. Tanyakan tindak lanjutnya
      kepada Head Store sebelum menghitung.</div>` : ''}

    <div class="section-title" style="margin:16px 2px 8px">Kunjungan Terakhir</div>
    <div style="max-height:22vh;overflow:auto">${sesi.length ? sesi.slice(0,8).map(r=>`
      <div class="sched" style="padding:10px 2px;border-bottom:1px solid var(--line)">
        <div style="flex:1;min-width:0">
          <div class="name" style="font-size:13px">${esc(r.ditutup.slice(0,10))}</div>
          <div class="sub">${esc(r.auditor||'—')} · ${esc(r.kode||'')}</div>
        </div>
        <span class="badge b-grey">TERKUNCI</span>
      </div>`).join('') : `<div class="sub" style="padding:4px 2px">Belum ada kunjungan tercatat.</div>`}</div>

    <div class="section-title" style="margin:16px 2px 8px">Catatan untuk Audit Ini</div>
    <textarea id="rsCatatan" class="input" rows="3"
      placeholder="Hal yang perlu diperiksa, janji tindak lanjut sebelumnya, atau pesan dari Head.">${esc(catatan.isi||'')}</textarea>
    ${catatan.oleh ? `<div class="sub" style="margin-top:6px">Terakhir ditulis ${esc(catatan.oleh)},
      ${new Date(catatan.pada).toLocaleString('id-ID',{dateStyle:'short',timeStyle:'short'})}</div>` : ''}
    <div style="display:grid;grid-template-columns:1fr 1.3fr;gap:9px;margin-top:14px">
      <button class="btn ghost" onclick="$('rsSheet').classList.remove('show')">Tutup</button>
      <button class="btn primary" onclick="simpanCatatanOutlet()">Simpan Catatan</button>
    </div>`;
  $('rsSheet').classList.add('show');
}

function simpanCatatanOutlet(){
  const outlet = $('outletSelect').value;
  const c = bacaCatatan();
  const isi = $('rsCatatan').value.trim();
  if(isi) c[normalNama(outlet)] = {isi, oleh:state.auditor.nama, pada:new Date().toISOString()};
  else delete c[normalNama(outlet)];
  tulisCatatan(c);
  $('rsSheet').classList.remove('show');
  perbaruiInfoDokumen();
  toast(isi ? 'Catatan disimpan' : 'Catatan dikosongkan');
}

function perbaruiInfoDokumen(){
  const outlet = $('outletSelect').value;
  const d = dokumenAktif(outlet);
  state.dokPakai = d;
  const tanpaHpp = d && d.item.every(i=>!i.hpp);
  $('dokInfo').innerHTML = d
    ? `<div class="notice blind">Dokumen aktif: periode <b>${esc(d.periode)}</b>,
        ${d.item.length} item, diunggah ${esc(d.oleh)}.</div>`
      + (tanpaHpp ? `<div class="notice gr">Dokumen ini tanpa kolom HPP. Selisih tetap
        terhitung dalam kuantitas, namun nilai Rupiahnya nol.</div>` : '')
    : `<div class="notice gr" style="border-left-color:var(--red)">Belum ada dokumen stock
        audit aktif untuk store ini. Audit tidak dapat dimulai sampai Admin atau Head
        mengunggahnya.</div>`;
  $('skuTotal').textContent = d ? d.item.length : 0;
  state.petaAudit = petaAuditTerakhir();
  const a = auditTerakhir(outlet);
  const c = bacaCatatan()[normalNama(outlet)];
  $('riwayatInfo').innerHTML =
    (a ? `<div class="notice ${a.umur < JEDA_MIN ? 'gr' : 'blind'}">Terakhir diaudit
        ${a.umur} hari lalu (${esc(a.tanggal)})${
        a.umur < JEDA_MIN ? `, di bawah jeda ${JEDA_MIN} hari` : ''}.</div>`
       : `<div class="notice gr">Outlet ini belum pernah tercatat diaudit.</div>`)
    + (c ? `<div class="notice info">Catatan: ${esc(c.isi.slice(0,120))}</div>` : '');
  const t = $('tblMulai'); if(t) t.disabled = !d;
}

