/* --------------------------- kamera --------------------------- */
/* =======================================================================
   KAMERA PEMINDAI

   Di dalam claude.ai halaman ini berjalan di sebuah bingkai (iframe), dan
   peramban hanya memberi kamera ke bingkai yang diizinkan induknya. Itu
   sebabnya getUserMedia yang berjalan mulus saat dibuka dari berkas di HP
   bisa ditolak di sini tanpa auditor melakukan kesalahan apa pun.

   Urutan yang dicoba:
   1. Minta izin lewat jalur bingkai (claude.use('permissions')) bila
      platform menyediakan nama yang menyangkut kamera. Dicari, bukan
      dipatok, karena nama izin itu milik platform dan dapat berubah.
   2. getUserMedia seperti biasa — pemindaian langsung dari video.
   3. Bila tetap ditolak: "Foto Barcode" — kamera bawaan HP dibuka lewat
      pemilih berkas, hasil fotonya dibaca BarcodeDetector. Jalur ini
      tidak butuh izin bingkai sama sekali, hanya lebih lambat satu
      ketukan per produk.
   4. Pemindai laser PDA dan Input Manual selalu ada.

   Kamera dibuka sendiri saat layar Menghitung tampil. Kalau auditor
   menolaknya sekali, tidak diminta lagi selama sesi — meminta berulang
   terbaca sebagai memaksa, dan penolakan kedua biasanya permanen.
   ======================================================================= */
let kameraDitolakSesi = false;

async function mintaIzinKameraBingkai(){
  try{
    if(!window.claude?.use) return;
    const perm = await window.claude.use('permissions');
    if(!perm) return;
    const peta = await perm.state();
    const nama = Object.keys(peta||{}).filter(k=>/camera|kamera|media|device/i.test(k));
    if(nama.length) await perm.request(nama);
  }catch(e){}
}

const diDalamBingkai = () => { try{ return window.self !== window.top; }catch(e){ return true; } };

async function startCamera(otomatis){
  const v=$('camVideo');
  if(state.stream){ if(!otomatis) stopCamera(); return; }
  if(otomatis && kameraDitolakSesi) return;
  if(!navigator.mediaDevices?.getUserMedia){
    $('scanHint').innerHTML = 'Peramban ini tidak menyediakan kamera langsung. '
      + 'Pakai <b>Foto Barcode</b>, pemindai laser PDA, atau Input Manual.';
    tampilkanTombolFotoBarcode(true);
    return;
  }
  try{
    await mintaIzinKameraBingkai();
    state.stream = await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});
    v.srcObject = state.stream; v.hidden=false; await v.play();
    $('camPlaceholder').style.display='none';
    $('cameraBox').classList.remove('mati');
    { const cl=$('camLabel'); if(cl) cl.textContent='Kamera perangkat'; }
    tampilkanTombolFotoBarcode(false);
    const tp = $('tblPemindai'); if(tp) tp.style.display = 'none';
    if(await detektor1D()){
      $('scanHint').textContent = 'Kamera aktif. Arahkan barcode garis ke kotak.';
      deteksiBarcode(v);
    }else{
      $('scanHint').textContent='Kamera aktif. Peramban ini belum mendukung deteksi barcode otomatis, gunakan Foto Barcode atau input manual.';
      tampilkanTombolFotoBarcode(true);
    }
  }catch(e){
    const ditolak = e && (e.name === 'NotAllowedError' || e.name === 'SecurityError');
    if(ditolak) kameraDitolakSesi = true;
    const sebab = ditolak && diDalamBingkai()
      ? 'Kamera langsung ditolak oleh bingkai claude.ai tempat halaman ini berjalan — bukan oleh Anda. '
      : ditolak ? 'Izin kamera ditolak. '
      : e && e.name === 'NotFoundError' ? 'Perangkat ini tidak punya kamera belakang yang terbaca. '
      : 'Kamera tidak dapat diakses. ';
    const bisaJendela = ditolak && diDalamBingkai();
    $('scanHint').innerHTML = sebab
      + (bisaJendela
          ? 'Tekan <b>Buka Pemindai</b>: kamera dibuka di jendela sendiri di luar bingkai, dan hasil pindainya langsung masuk ke sini. '
          : '')
      + 'Atau pakai <b>Foto Barcode</b>: kamera HP terbuka, fotonya dibaca otomatis. '
      + 'Pemindai laser PDA dan Input Manual juga tetap jalan.';
    tampilkanTombolFotoBarcode(true);
    const tp = $('tblPemindai'); if(tp) tp.style.display = bisaJendela ? '' : 'none';
    if(!otomatis) toast('Kamera langsung tidak tersedia — pakai Foto Barcode');
  }
}

/* Tombol Foto Barcode kini jalur utama, jadi tidak pernah disembunyikan.
   Argumennya dipertahankan supaya pemanggil lama tidak perlu diubah. */
function tampilkanTombolFotoBarcode(ya){
  const b = $('tblFotoBarcode'); if(b) b.style.display = '';
}

/* =======================================================================
   FOTO BARCODE — jalur utama

   Kamera langsung sering ditolak oleh bingkai claude.ai tempat halaman ini
   berjalan, dan penolakan itu di luar kendali auditor. Jalur foto memakai
   pemilih berkas bawaan HP, sehingga tidak memerlukan izin bingkai sama
   sekali. Harganya satu ketukan lebih banyak per produk.

   Urutan pembacaan, berhenti pada yang pertama berhasil:
   1. BarcodeDetector bawaan peramban (Chrome Android) — paling cepat.
   2. ZXing MultiFormatOneDReader dengan TRY_HARDER, dicoba pada tiga ukuran
      gambar (1600, 1000, 2400 px) dan sekali lagi setelah diputar 90°,
      karena barcode pada botol sering terfoto berdiri.
   3. Pembaca EAN-13/UPC-A bawaan halaman ini, yang hanya memakai kanvas,
      sebagai cadangan bila pustaka ZXing gagal dimuat.

   Hanya barcode garis (1D) yang diterima. Kode QR sengaja tidak dibaca:
   botol membawa QR pita cukai yang tidak membedakan SKU, dan bila ikut
   terbaca auditor akan mencatat produk yang salah.
   ======================================================================= */
const FMT_1D = ['ean_13','ean_8','upc_a','upc_e','code_128','code_39','code_93','itf','codabar'];
let _det1D = null, _det1DSiap = false;
async function detektor1D(){
  if(_det1DSiap) return _det1D;
  _det1DSiap = true;
  try{
    if('BarcodeDetector' in window){
      const ada = await BarcodeDetector.getSupportedFormats();
      const f = FMT_1D.filter(x => ada.includes(x));
      if(f.length) _det1D = new BarcodeDetector({formats:f});
    }
  }catch(e){ _det1D = null; }
  return _det1D;
}

const _zx = {};
function zxPembaca(keras){
  const k = keras ? 'keras' : 'cepat';
  if(_zx[k]) return _zx[k];
  const B = ZXing.BarcodeFormat, h = new Map();
  h.set(ZXing.DecodeHintType.POSSIBLE_FORMATS,
        [B.EAN_13,B.EAN_8,B.UPC_A,B.UPC_E,B.CODE_128,B.CODE_39,B.CODE_93,B.ITF,B.CODABAR]);
  if(keras) h.set(ZXing.DecodeHintType.TRY_HARDER, true);
  return _zx[k] = {r:new ZXing.MultiFormatOneDReader(h), h};
}
function zxBaca(kanvas, keras){
  if(typeof ZXing === 'undefined') return '';
  let p; try{ p = zxPembaca(keras); }catch(e){ return ''; }
  try{
    const bmp = new ZXing.BinaryBitmap(new ZXing.HybridBinarizer(
                  new ZXing.HTMLCanvasElementLuminanceSource(kanvas)));
    const h = p.r.decode(bmp, p.h);
    return h ? h.getText() : '';
  }catch(e){ return ''; }
  finally{ try{ p.r.reset(); }catch(e){} }
}

/* Menolak isi kode QR yang kebetulan terbaca, dan kode yang terlalu panjang
   untuk sebuah barcode garis produk. */
function sah1D(t){
  t = String(t==null?'':t).trim().replace(/\s+/g,'');
  if(!t || t.length > 48) return '';
  if(/^https?:\/\//i.test(t)) return '';
  return t;
}

/* Bunyi pendek sebagai penanda. Di gudang yang bising dan remang, auditor
   sering tidak sempat melihat layar setiap kali memotret. */
function bunyiPindai(berhasil){
  try{
    const AC = window.AudioContext || window.webkitAudioContext; if(!AC) return;
    bunyiPindai._c = bunyiPindai._c || new AC();
    const c = bunyiPindai._c; if(c.state === 'suspended') c.resume();
    const o = c.createOscillator(), g = c.createGain();
    o.connect(g); g.connect(c.destination);
    o.type = 'square'; o.frequency.value = berhasil ? 1180 : 320;
    const t = c.currentTime, lama = berhasil ? .12 : .28;
    g.gain.setValueAtTime(.0001, t);
    g.gain.exponentialRampToValueAtTime(.2, t + .012);
    g.gain.exponentialRampToValueAtTime(.0001, t + lama);
    o.start(t); o.stop(t + lama + .02);
  }catch(e){}
}

function muatGambar(berkas){
  return new Promise((res, rej)=>{
    const url = URL.createObjectURL(berkas), im = new Image();
    im.onload = ()=>{ im._url = url; res(im); };
    im.onerror = ()=>{ URL.revokeObjectURL(url); rej(new Error('gambar tidak terbaca')); };
    im.src = url;
  });
}

/* Mengembalikan kode yang terbaca dari sebuah berkas foto, atau '' bila
   tidak ada. Dipakai layar hitung dan layar Barcode Produk. */
async function bacaKodeDariFoto(f){
  let kode = '';
  try{
    const gbr = await muatGambar(f);
    const det = await detektor1D();
    if(det){ try{ const r = await det.detect(gbr); if(r && r.length) kode = sah1D(r[0].rawValue); }catch(e){} }
    if(!kode){
      for(const maks of [1600, 1000, 2400]){
        const sk = Math.min(1, maks / Math.max(gbr.width, gbr.height));
        const c = document.createElement('canvas');
        c.width  = Math.max(1, Math.round(gbr.width  * sk));
        c.height = Math.max(1, Math.round(gbr.height * sk));
        c.getContext('2d', {willReadFrequently:true}).drawImage(gbr, 0, 0, c.width, c.height);
        kode = sah1D(zxBaca(c, true)); if(kode) break;
        /* Barcode terfoto berdiri: diputar 90° lalu dicoba sekali lagi. */
        const cp = document.createElement('canvas'); cp.width = c.height; cp.height = c.width;
        const x2 = cp.getContext('2d', {willReadFrequently:true});
        x2.translate(cp.width/2, cp.height/2); x2.rotate(Math.PI/2);
        x2.drawImage(c, -c.width/2, -c.height/2);
        kode = sah1D(zxBaca(cp, true)); if(kode) break;
      }
    }
    if(gbr._url) URL.revokeObjectURL(gbr._url);
    if(!kode) kode = sah1D(await bacaBarcodeDariGambar(f));
  }catch(e){ kode = ''; }
  return kode;
}

async function fotoBarcodeDipilih(input){
  const f = input.files && input.files[0]; input.value = '';
  if(!f) return;
  $('scanHint').textContent = 'Membaca barcode dari foto…';
  const kode = await bacaKodeDariFoto(f);
  if(!kode){
    bunyiPindai(false);
    $('scanHint').innerHTML = '<b>Barcode garis tidak terbaca dari foto itu.</b> '
      + 'Potret ulang dari jarak 10–20 cm, lurus menghadap label, cukup terang dan tidak buram. '
      + 'Pastikan yang difoto barcode garis, bukan kode QR pita cukai — QR memang tidak dibaca '
      + 'karena tidak membedakan SKU. Bila tetap gagal, ketik angkanya lewat Input Manual.';
    return;
  }
  bunyiPindai(true);
  $('scanHint').textContent = 'Terbaca: ' + kode;
  cariProduk(kode);
}

function stopCamera(){
  if(!state.stream) return;
  state.stream.getTracks().forEach(t=>t.stop());
  state.stream=null;
  const v=$('camVideo'); v.srcObject=null; v.hidden=true;
  const ph=$('camPlaceholder'); if(ph) ph.style.display='';
  $('cameraBox').classList.add('mati');
  { const cl=$('camLabel'); if(cl) cl.textContent='Mode foto'; }
}
async function deteksiBarcode(video){
  const det = await detektor1D();
  if(!det) return;
  const loop = async()=>{
    if(!state.stream) return;
    try{
      const codes = await det.detect(video);
      const k = codes && codes.length ? sah1D(codes[0].rawValue) : '';
      if(k && !document.getElementById('countModal').classList.contains('show')){
        bunyiPindai(true); cariProduk(k);
      }
    }catch(e){}
    requestAnimationFrame(loop);
  };
  loop();
}

