/* =======================================================================
   SINKRONISASI DOKUMEN DI TENGAH PENGHITUNGAN

   Stok pembanding dibekukan saat sesi dibuka. Bila Admin atau Head mengunggah
   perbaikan sewaktu auditor sedang menghitung, auditor dapat menariknya lewat
   tombol Sinkronkan.

   Dua hal ditangani terang-terangan. Pertama, SKU yang sudah terhitung dan
   stoknya berubah akan berubah pula selisihnya — SKU itu disebut satu per satu
   sebelum sinkron dijalankan, bukan diam-diam bergeser. Kedua, pemetaan
   hitungan memakai nama produk, bukan nomor baris, karena urutan baris pada
   dokumen baru bisa berbeda dan nomor baris akan menunjuk produk lain.
   ======================================================================= */
function dokumenBerubah(){
  if(!state.dokRef) return null;
  const d = dokumenAktif(state.outlet);
  if(!d) return {hilang:true};
  if(d.id === state.dokRef.id && d.diunggah === state.dokRef.diunggah) return null;
  return {dok:d};
}

function bedaDokumen(baru){
  const lamaNama = {};                                   // nama -> sku lama
  KAT().forEach(m => lamaNama[kunciNama(m.nama)] = m.sku);
  const kat = katalogDariDokumen(baru);

  const berubah = [], tambah = [], hapus = [];
  const baruNama = new Set(kat.map(m => kunciNama(m.nama)));

  kat.forEach(m => {
    const k = kunciNama(m.nama);
    const skuLama = lamaNama[k];
    if(!skuLama){ tambah.push(m); return; }
    const v = snap(skuLama);
    if(v.awal !== m.awal || v.masuk !== m.masuk || v.keluar !== m.keluar || v.sistem !== m.sistem)
      berubah.push({nama:m.nama, skuLama, lama:v, baru:m,
                    sudahDihitung: state.hitung.has(skuLama)});
  });
  KAT().forEach(m => { if(!baruNama.has(kunciNama(m.nama))) hapus.push(m); });

  return {kat, berubah, tambah, hapus,
          hapusTerhitung: hapus.filter(m => state.hitung.has(m.sku))};
}

function bukaSinkron(){
  const cek = dokumenBerubah();
  if(!cek){
    toast('Dokumen sudah yang terbaru');
    return;
  }
  if(cek.hilang){
    $('syIsi').innerHTML = `<div class="handle"></div>
      <h3>Dokumen Dibatalkan</h3>
      <div class="notice gr" style="border-left-color:var(--red)">Dokumen yang dipakai sesi ini
        sudah dibatalkan Admin atau Head. Hitungan yang sudah ada tetap tersimpan, namun
        sesi sebaiknya ditutup dan diulang memakai dokumen pengganti.</div>
      <button class="btn ghost" style="margin-top:14px" onclick="tutupSinkron()">Tutup</button>`;
    $('sySheet').classList.add('show');
    return;
  }

  const b = bedaDokumen(cek.dok);
  state.sinkronBeda = b; state.sinkronDok = cek.dok;
  const kena = b.berubah.filter(x => x.sudahDihitung);

  $('syIsi').innerHTML = `
    <div class="handle"></div>
    <h3>Sinkronkan Dokumen Stok</h3>
    <p class="note">Ada pembaruan dokumen untuk ${esc(state.outlet)} dari
      ${esc(cek.dok.oleh)}, periode ${esc(cek.dok.periode)}.</p>
    <div class="split">
      <div class="box"><div class="lab">Stok berubah</div><div class="num">${b.berubah.length}</div></div>
      <div class="box"><div class="lab">Sudah terhitung</div><div class="num" style="color:${kena.length?'var(--red)':'var(--ink)'}">${kena.length}</div></div>
      <div class="box"><div class="lab">Item baru</div><div class="num" style="color:var(--green)">${b.tambah.length}</div></div>
      <div class="box"><div class="lab">Item hilang</div><div class="num v-minus">${b.hapus.length}</div></div>
    </div>

    ${kena.length ? `
      <div class="notice gr" style="border-left-color:var(--red);margin-top:12px">
        <b>${kena.length} SKU sudah Anda hitung dan stoknya berubah.</b> Selisihnya akan ikut
        berubah setelah sinkron. Periksa apakah hitungan fisiknya masih sesuai.</div>
      <div style="max-height:26vh;overflow:auto;border:1px solid var(--line);border-radius:14px;margin-top:9px">
        ${kena.slice(0,30).map(x=>`<div class="sched" style="padding:10px 12px">
          <div style="flex:1;min-width:0">
            <div class="name" style="font-size:13px">${esc(x.nama)}</div>
            <div class="sub">Stok akhir ${num(x.lama.sistem)} &rarr; ${num(x.baru.sistem)}
              · fisik tercatat ${num(state.hitung.get(x.skuLama))}</div>
          </div></div>`).join('')}
      </div>` : `<div class="notice blind" style="margin-top:12px">Tidak ada SKU terhitung
        yang stoknya berubah. Sinkron aman dijalankan.</div>`}

    ${b.hapusTerhitung.length ? `<div class="notice gr" style="margin-top:12px">
      ${b.hapusTerhitung.length} SKU yang sudah Anda hitung tidak ada lagi pada dokumen baru.
      Hitungannya akan dibuang: ${b.hapusTerhitung.slice(0,5).map(m=>esc(m.nama)).join('; ')}${
      b.hapusTerhitung.length>5?'; dan lainnya':''}.</div>` : ''}

    <div style="display:grid;grid-template-columns:1fr 1.3fr;gap:9px;margin-top:16px">
      <button class="btn ghost" onclick="tutupSinkron()">Nanti Saja</button>
      <button class="btn primary" onclick="jalankanSinkron()">Sinkronkan Sekarang</button>
    </div>`;
  $('sySheet').classList.add('show');
}
function tutupSinkron(){ $('sySheet').classList.remove('show'); }

function jalankanSinkron(){
  const b = state.sinkronBeda, d = state.sinkronDok;
  if(!b || !d) return;

  // Hitungan dipindahkan berdasarkan nama produk, bukan nomor baris.
  const namaKeFisik = new Map();
  state.hitung.forEach((qty, sku) => {
    const m = KAT().find(x => x.sku === sku);
    if(m) namaKeFisik.set(kunciNama(m.nama), qty);
  });

  state.katalog = b.kat;
  state.dokRef = {id:d.id, periode:d.periode, berkas:d.berkas||'', diunggah:d.diunggah};
  state.snapshot = {};
  b.kat.forEach(m => state.snapshot[m.sku] =
    {awal:m.awal ?? 0, masuk:m.masuk ?? 0, keluar:m.keluar ?? 0, sistem:m.sistem});

  const baru = new Map();
  b.kat.forEach(m => {
    const q = namaKeFisik.get(kunciNama(m.nama));
    if(q !== undefined) baru.set(m.sku, q);
  });
  const dibuang = namaKeFisik.size - baru.size;
  state.hitung = baru;

  (state.sinkronRiwayat ||= []).push({
    pada: new Date().toISOString(), oleh: d.oleh, periode: d.periode,
    berubah: b.berubah.length, terhitungTerdampak: b.berubah.filter(x=>x.sudahDihitung).length,
    tambah: b.tambah.length, hapus: b.hapus.length, hitunganDibuang: dibuang
  });

  simpanDraft(); tutupSinkron();
  renderItemList(); updateCounters(); tandaiSinkron();
  toast(dibuang ? `Tersinkron. ${dibuang} hitungan dibuang karena itemnya tidak ada lagi.`
                : 'Dokumen tersinkron');
}

function tandaiSinkron(){
  const el = $('syInfo'); if(!el) return;
  const ada = dokumenBerubah();
  const r = state.sinkronRiwayat || [];
  el.innerHTML = ada && !ada.hilang
    ? `<b style="color:var(--orange)">Ada pembaruan dokumen. Tekan Sinkronkan.</b>`
    : `Dokumen periode ${esc(state.dokRef?.periode || '—')}${
        r.length ? ` · disinkronkan ${r.length}×` : ''}.`;
}

