/* --------------------------- jadwal audit --------------------------- */
const hariIni = () => {const d=new Date();d.setHours(0,0,0,0);return d};
/* Tanggal lokal, bukan toISOString. Di WIB dan WITA, tengah malam waktu
   setempat masih pukul 17.00 atau 16.00 UTC hari sebelumnya, sehingga
   toISOString mengembalikan tanggal kemarin sepanjang pagi hingga sore. */
const kunciTgl = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

/* Menyusun rencana kunjungan satu bulan penuh.
   Hari Minggu dikecualikan, dan outlet diputar berurutan sehingga setiap
   outlet kembali dikunjungi setelah satu putaran penuh. */
function buatJadwal(daftarOutlet){
  const outlet = daftarOutlet || PROFIL.outlet;
  const now=new Date(), th=now.getFullYear(), bl=now.getMonth();
  const akhir=new Date(th,bl+1,0).getDate();
  const kini=hariIni();
  const hasil=[]; let idx=0, lewat=0;

  for(let d=1; d<=akhir; d++){
    const tgl=new Date(th,bl,d);
    if(tgl.getDay()===0) continue;                    // Minggu dikecualikan
    const kunjungan=[];
    for(let k=0;k<PROFIL.perHari;k++){
      const nama=outlet[idx % outlet.length]; idx++;
      let status;
      if(tgl<kini){ lewat++; status = (lewat%9===4) ? 'TERLEWAT' : 'SELESAI'; }
      else if(tgl.getTime()===kini.getTime()) status='HARI INI';
      else status='TERJADWAL';
      kunjungan.push({outlet:nama, status});
    }
    hasil.push({tgl,kunjungan});
  }
  return hasil;
}

/* Auditor membaca penugasan yang ditetapkan Head. Tidak ada jalur ubah
   di sisi auditor: perubahan jadwal adalah kewenangan Head. */
const semuaKunjungan = () => penugasanNik(PROFIL.nik)
  .map(pg=>({outlet:pg.outlet, status:pg.status, tgl:dariKunci(pg.tgl), riwayat:pg.riwayat}))
  .sort((a,b)=>a.tgl-b.tgl);
const sisaKunjungan = () =>
  semuaKunjungan().filter(k=>k.status==='TERJADWAL'||k.status==='HARI INI').length;

function badgeStatus(st){
  const c = st==='SELESAI'?'b-green' : st==='TERLEWAT'?'b-red'
          : st==='HARI INI'?'b-orange' : 'b-grey';
  return `<span class="badge ${c}">${st}</span>`;
}
const tglPanjang = d => HARI[d.getDay()]+', '+d.getDate()+' '+BULAN[d.getMonth()];
const tglPendek  = d => HARIS[d.getDay()]+', '+d.getDate()+' '+BULAN[d.getMonth()].slice(0,3);

function setJadwalFilter(f){
  state.jadwalFilter=f;
  $('jdChipSemua').classList.toggle('on',f==='semua');
  $('jdChipBelum').classList.toggle('on',f==='belum');
  renderJadwal();
}

function renderJadwal(){
  const now=new Date(), kini=hariIni();
  $('jdBulan').textContent = BULAN[now.getMonth()]+' '+now.getFullYear();

  const semua=semuaKunjungan();
  $('jdSisa').textContent  = sisaKunjungan();
  $('jdLewat').textContent = semua.filter(k=>k.status==='TERLEWAT').length;
  $('jdHari').textContent  = new Set(semuaKunjungan().filter(k=>k.tgl>=kini)
                                .map(k=>kunci(k.tgl))).size;

  const akhirBulan=new Date(now.getFullYear(),now.getMonth()+1,0);
  $('jdAturan').innerHTML = `Rencana disusun sampai ${tglPanjang(akhirBulan)}.
    ${PROFIL.perHari} outlet per hari, hari Minggu dikecualikan, dan
    Jadwal ditetapkan Head Internal Auditor. Bila ada kunjungan yang perlu
    digeser, ajukan ke Head — penjadwalan ulang tidak dapat dilakukan dari
    perangkat auditor.`;

  // Tampilan bawaan menghadap ke depan: hari ini sampai akhir bulan.
  // Saringan kedua memunculkan kunjungan terlewat dari awal bulan.
  const perHari = {};
  semuaKunjungan().forEach(k=>{
    if(state.jadwalFilter==='belum' && k.status==='SELESAI') return;
    if(state.jadwalFilter==='semua' && k.tgl<kini) return;
    (perHari[kunci(k.tgl)] ||= []).push(k);
  });
  const hari = Object.keys(perHari).sort()
    .map(kt=>({tgl:dariKunci(kt), kunjungan:perHari[kt]}));

  $('jadwalList').innerHTML = hari.length ? hari.map(h=>{
    const ini = h.tgl.getTime()===kini.getTime();
    const lalu = h.tgl<kini;
    return `<div class="day-card ${ini?'today':''} ${lalu?'past':''}">
      <div class="day-head">
        <div class="day-num">${h.tgl.getDate()}</div>
        <div style="flex:1;min-width:0">
          <div class="day-dow">${HARI[h.tgl.getDay()]}${ini?' · Hari ini':''}</div>
          <div class="day-sub">${h.tgl.getDate()} ${BULAN[h.tgl.getMonth()]} ${h.tgl.getFullYear()}</div>
        </div>
        <span class="badge b-grey">${h.kunjungan.length} outlet</span>
      </div>
      ${h.kunjungan.map((k,i)=>`
        <div class="sched">
          <div class="ord">${i+1}</div>
          <div style="flex:1;min-width:0">
            <div class="name">${esc(k.outlet)}</div>
            <div class="sub">${esc(regionOutlet(k.outlet))}${
              k.riwayat && k.riwayat.length
                ? ' · <b style="color:var(--orange)">dijadwalkan ulang: '+esc(k.riwayat[k.riwayat.length-1].alasan)+'</b>'
                : ''}</div>
          </div>
          ${badgeStatus(k.status)}
        </div>`).join('')}
    </div>`;
  }).join('') : `<div class="card center" style="color:var(--muted);font-size:12px;padding:26px">
      Tidak ada kunjungan pada saringan ini.</div>`;
}

