function openMenu(){
  /* Beranda, Jadwal, dan Profil hanya berlaku bagi auditor lapangan; peran
     pengelola tidak punya outlet binaan maupun jadwal kunjungan sendiri. */
  const lapangan = adalahLapangan();
  const head = state.peran === 'head';
  $('menuWho').textContent = lapangan
    ? PROFIL.nama+' · '+PROFIL.nik+' · Kode '+PROFIL.kode
    : state.auditor.nama+' · '+state.auditor.nik+' · '+state.auditor.jabatan;
  document.querySelectorAll('#menuSheet .menu-item').forEach(b=>{
    const t = b.getAttribute('onclick')||'';
    const khususAuditor = t.includes("'jadwal'")||t.includes("'profil'")||t.includes("'dashboard'");
    /* Butir yang hanya untuk Head dan Admin disembunyikan dari auditor. */
    const perlu = Object.entries(HAK_LAYAR).find(([layar]) => t.includes(`'${layar}'`));
    if(perlu){ b.style.display = boleh(perlu[1]) ? '' : 'none'; return; }
    if(t.includes("'arsip'") || t.includes('gantiTema') || t.includes('bukaGantiSandi')){
      b.style.display=''; return; }
    b.style.display = (!lapangan && khususAuditor) ? 'none' : '';
  });
  if(lapangan) $('menuJadwalSub').textContent = sisaKunjungan()+' kunjungan tersisa bulan ini';
  const ar = bacaArsip().filter(r => !lapangan || r.nik === state.auditor?.nik);
  terapkanTema(temaSekarang());
  $('menuArsipSub').textContent = ar.length ? ar.length+' audit terkunci' : 'Belum ada audit ditutup';
  $('menuLogoutSub').textContent = state.sesiAktif
    ? 'Ada sesi audit berjalan' : 'Akhiri sesi aplikasi';
  $('menuSheet').classList.add('show');
}
function closeMenu(){$('menuSheet').classList.remove('show')}
function goMenu(id){closeMenu();showScreen(id)}

/* Keluar saat masih ada hasil belum terkirim adalah kehilangan permanen,
   jadi jumlahnya disebutkan satu per satu sebelum dikonfirmasi. */
function confirmLogout(){
  closeMenu();
  const belum = state.hitung.size + state.checklist.size + state.temuan.length;
  if(belum){
    // Hasil tidak lagi hilang saat keluar: draft disimpan dan ditawarkan lagi saat masuk.
    simpanDraft();
    $('logoutWarn').textContent = 'Hasil sesi '+state.outlet+' disimpan sebagai draft di perangkat ini.';
    $('logoutDetail').innerHTML = `<div class="notice blind">
      ${state.hitung.size} hitungan SKU · ${state.checklist.size} butir checklist ·
      ${state.temuan.length} temuan tersimpan. Saat masuk kembali dengan NIK yang sama,
      sesi ini akan ditawarkan untuk dilanjutkan.</div>`;
    $('btnLogout').textContent = 'Keluar';
  }else{
    $('logoutWarn').textContent = 'Anda akan diminta memasukkan NIK dan PIN lagi.';
    $('logoutDetail').innerHTML = '';
    $('btnLogout').textContent = 'Keluar';
  }
  $('logoutSheet').classList.add('show');
}
function closeLogout(){$('logoutSheet').classList.remove('show')}
function doLogout(){
  closeLogout(); stopCamera(); simpanDraft();     // draft sengaja dipertahankan
  state.hitung.clear(); state.checklist.clear();
  state.temuan=[]; state.foto=null; state.sesiAktif=false;
  state.auditor=null; pads.signPic=null; pads.signAud=null;
  state.peran='staff'; state.tim=[]; state.penugasan=[];
  state.pnAktif=null; state.kpiAktif=null; state.tgAktif=null;
  $('loginPass').value=''; $('loginId').value=''; $('loginGalat').textContent='';
  $('mainApp').style.display='none';
  $('loginScreen').style.display='flex';
  toast('Anda sudah keluar');
}

