/* --------------------------- rekap --------------------------- */
function renderReview(){
  const rows = barisHasil();
  const minus = rows.filter(r=>r.arah==='MINUS');
  const plus  = rows.filter(r=>r.arah==='PLUS');
  const nMinus = minus.reduce((a,r)=>a+r.nilai,0);
  const nPlus  = plus.reduce((a,r)=>a+r.nilai,0);

  $('lossHero').textContent = rp(Math.abs(nMinus));
  $('reviewSku').textContent = rows.length;
  $('reviewVar').textContent = rows.filter(r=>r.arah!=='COCOK').length;
  $('minusVal').textContent = rp(Math.abs(nMinus));
  $('plusVal').textContent  = rp(Math.abs(nPlus));
  $('minusQty').textContent = num(minus.reduce((a,r)=>a+Math.abs(r.bersih),0));
  $('plusQty').textContent  = '+'+num(plus.reduce((a,r)=>a+r.bersih,0));

  /* Katalog sesi, bukan master bawaan. Dokumen PATI memuat 574 SKU sedangkan
     master 1.736, sehingga memakai master membuat cakupan selalu terbaca
     jauh dari penuh padahal seluruh SKU dokumen sudah dihitung. */
  const belum = KAT().length - state.hitung.size;
  const ckBelum = ckTotal() - ckDijawab();
  $('coverWarn').innerHTML = (belum||ckBelum)
    ? `<div class="notice gr">${belum?belum+' SKU belum dihitung. ':''}${ckBelum?ckBelum+' butir checklist belum dijawab. ':''}Sesi tetap bisa ditutup, namun cakupan tercatat belum penuh.</div>`
    : `<div class="notice blind">Cakupan penuh: seluruh SKU dihitung dan checklist terjawab.</div>`;

  const gagal = ckTidakSesuai();
  $('ckFailBlock').innerHTML = gagal.length ? `
    <div class="section-title">Checklist Tidak Sesuai</div>
    <div class="list">${gagal.map(i=>`<div class="item">
      <div class="name">${esc(i.uraian)}</div>
      <div class="sub">${esc(i.kode)}${state.checklist.get(i.kode+':note')?' · '+esc(state.checklist.get(i.kode+':note')):''}</div>
    </div>`).join('')}</div>` : '';

  $('resultTable').innerHTML = rows.map(r=>{
    const kelas = r.arah==='MINUS'?'v-minus':r.arah==='PLUS'?'v-plus':'v-match';
    return `<tr>
      <td style="font-weight:800;white-space:normal;min-width:110px">${esc(r.p.nama)}</td>
      <td>${num(r.sistem)}</td>
      <td>${num(r.fisik)}</td>
      <td style="font-weight:900" class="${kelas}">${r.bersih>0?'+':''}${num(r.bersih)}</td>
      <td style="font-weight:900" class="${kelas}">${r.nilai?rp(Math.abs(r.nilai)):'—'}</td>
    </tr>`;
  }).join('') || `<tr><td colspan="5" style="text-align:center;color:var(--muted)">Belum ada data.</td></tr>`;
}

/* --------------------------- temuan --------------------------- */
function calcOutstanding(){
  const nma=+$('fMinus').value||0, up=+$('fPlus').value||0, pay=+$('fPay').value||0;
  $('fQtyEcho').textContent = num(+$('fQty').value||0) + ' unit';
  $('fMinusEcho').textContent = rp(nma);
  $('fPlusEcho').textContent  = rp(up);
  $('fPayEcho').textContent   = rp(pay);
  const o = outstanding(nma,up,pay);
  $('findingLoss').textContent = rp(o);
  $('findingLoss').className = 'result-number ' + (o<0?'v-plus':o>0?'v-minus':'v-match');
  const b=$('findingClass');
  if(o){const k=klasifikasi(o); b.textContent=k;
    b.className='badge '+(k==='CRITICAL'?'b-red':k==='MAJOR'?'b-orange':'b-grey');}
  else {b.textContent='—';b.className='badge b-grey'}
}
function openFinding(){
  // Nilai minus dari hasil hitung diusulkan sebagai titik awal, tetap bisa diubah.
  const nMinus = Math.abs(barisHasil().filter(r=>r.arah==='MINUS').reduce((a,r)=>a+r.nilai,0));
  if(nMinus && +$('fMinus').value===0) $('fMinus').value = Math.round(nMinus);
  /* Kuantitas minus diambil dari hasil penghitungan agar tidak diketik ulang
     dan tidak berbeda dari angka yang sudah terkunci di rekap. */
  const qMinus = barisHasil().filter(r=>r.arah==='MINUS').reduce((a,r)=>a+Math.abs(r.bersih),0);
  if(qMinus && +$('fQty').value===0) $('fQty').value = Math.round(qMinus);
  calcOutstanding(); showScreen('finding');
}
async function photoAdded(){
  const berkas = [...$('photoInput').files];
  if(!berkas.length) return;
  const ket = `${state.outlet||''} · ${$('findingType').value}`;
  for(const f of berkas){
    $('photoBox').innerHTML = `<div class="helper">Memberi cap waktu dan lokasi pada
      foto ${state.fotoDaftar.length+1}…</div>`;
    const h = await prosesFotoBukti(f, ket);
    state.fotoDaftar.push(h);
  }
  $('photoInput').value = '';
  gambarDaftarFoto();
}

/* Foto ditampilkan sebagai daftar bernomor. Mata untuk memeriksa ulang
   hasilnya sebelum sesi ditutup, silang untuk membuang yang kurang jelas —
   keduanya perlu, karena foto yang buram baru ketahuan setelah diperbesar. */
function gambarDaftarFoto(){
  const d = state.fotoDaftar;
  if(!d.length){ $('photoBox').innerHTML = '<div class="helper">Belum ada lampiran.</div>'; return; }
  const kb = t => Math.round(t.length * 0.75 / 1024);
  $('photoBox').innerHTML = d.map((x,i)=>{
    const l = x.lokasi;
    return `<div class="sched" style="padding:10px 2px;border-bottom:1px solid var(--line)">
      <div style="flex:1;min-width:0">
        <div class="name" style="font-size:13px">Foto ${i+1}
          <span class="sub">· ${kb(x.foto)} KB</span></div>
        <div class="sub">${l.status==='ada'
          ? `${l.lat.toFixed(5)}, ${l.lon.toFixed(5)} · ±${l.akurasi} m`
          : `<b style="color:var(--orange)">${esc(KET_LOKASI[l.status])}</b>`}</div>
      </div>
      <button class="btn ghost" style="width:auto;padding:8px 11px;margin-right:6px"
              aria-label="Lihat foto ${i+1}" onclick="lihatFoto(${i})">👁</button>
      <button class="btn ghost" style="width:auto;padding:8px 11px;color:var(--red);border-color:var(--red)"
              aria-label="Hapus foto ${i+1}" onclick="hapusFoto(${i})">✕</button>
    </div>`;
  }).join('') + `<div class="helper" style="margin-top:8px">${d.length} foto ·
    ${d.reduce((a,x)=>a+kb(x.foto),0)} KB · disimpan 9:16 terkompres.</div>`;
}

function lihatFoto(i){
  const x = state.fotoDaftar[i], l = x.lokasi;
  $('lfIsi').innerHTML = `
    <div class="handle"></div>
    <h3>Foto ${i+1}</h3>
    <p class="note">${new Date(x.diambil).toLocaleString('id-ID',{dateStyle:'long',timeStyle:'short'})}</p>
    <img src="${x.foto}" alt="Bukti foto ${i+1}"
         style="width:100%;border-radius:16px;display:block;max-height:58vh;object-fit:contain;background:#000">
    <div class="notice ${l.status==='ada'?'blind':'gr'}" style="margin-top:10px">${l.status==='ada'
      ? `Koordinat ${l.lat.toFixed(6)}, ${l.lon.toFixed(6)} · ketelitian ±${l.akurasi} m`
      : `${esc(KET_LOKASI[l.status])}. Foto tetap bercap waktu, namun tanpa titik koordinat.`}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px">
      <button class="btn" style="background:var(--red);color:#fff" onclick="hapusFoto(${i}, true)">Hapus Foto</button>
      <button class="btn primary" onclick="$('lfSheet').classList.remove('show')">Sudah Sesuai</button>
    </div>`;
  $('lfSheet').classList.add('show');
}

function hapusFoto(i, dariPratinjau){
  state.fotoDaftar.splice(i,1);
  if(dariPratinjau) $('lfSheet').classList.remove('show');
  gambarDaftarFoto(); toast('Foto dihapus');
}
function saveFinding(){
  const uraian=$('findingDesc').value.trim();
  if(!uraian){toast('Tulis uraian temuan lebih dulu');return}
  const nma=+$('fMinus').value||0, up=+$('fPlus').value||0, pay=+$('fPay').value||0;
  const qty=+$('fQty').value||0;
  if(nma > 0 && pay > nma){ toast('Payment tidak boleh melebihi Nominal Minus Asset'); return; }
  state.temuan.push({jenis:$('findingType').value, uraian, qtyMinus:qty, nma, up, pay,
    out:outstanding(nma,up,pay), fotoDaftar:[...state.fotoDaftar],
    foto:state.fotoDaftar[0]?.foto || null});
  $('findingDesc').value=''; $('fQty').value=0; $('fMinus').value=0; $('fPlus').value=0; $('fPay').value=0;
  state.fotoDaftar=[]; $('photoInput').value=''; gambarDaftarFoto();
  calcOutstanding(); renderFindings(); updateCounters(); simpanDraft();
  toast('Temuan tersimpan');
}
function renderFindings(){
  const el=$('findingList');
  $('findingCount').textContent = state.temuan.length;
  if(!state.temuan.length){
    el.innerHTML='<div class="card center" style="color:var(--muted);font-size:12px">Belum ada temuan dicatat.</div>';
    return;
  }
  el.innerHTML = [...state.temuan].sort((a,b)=>Math.abs(b.out)-Math.abs(a.out)).map(t=>{
    const k=klasifikasi(t.out);
    return `<div class="item"><div class="row">
      <div style="min-width:0">
        <div class="name">${esc(t.jenis)}</div>
        <div class="sub">${esc(t.uraian.slice(0,60))}</div>
      </div>
      <div style="text-align:right">
        <span class="badge ${k==='CRITICAL'?'b-red':k==='MAJOR'?'b-orange':'b-grey'}">${k}</span>
        <div style="font-weight:900;font-size:14px;margin-top:5px" class="${t.out<0?'v-plus':'v-minus'}">${rp(Math.abs(t.out))}</div>
      </div></div>
      ${t.foto?`<img class="thumb-img" src="${t.foto}" alt="">`:''}
    </div>`;
  }).join('');
}

/* Kategori kesimpulan dibuat baku, bukan tulisan bebas, supaya hasil antar
   outlet dapat direkap dan dibandingkan. Catatan bebas tetap diminta untuk
   menampung hal khusus yang tidak tertampung oleh kategori. */
const KESIMPULAN = [
  {kode:'WAJAR',      nama:'Wajar',                 warna:'b-green',
   ket:'Tidak ditemukan penyimpangan berarti.'},
  {kode:'PERHATIAN',  nama:'Perlu Perhatian',       warna:'b-orange',
   ket:'Ada selisih, masih dapat ditangani outlet sendiri.'},
  {kode:'TINDAK',     nama:'Perlu Tindak Lanjut',   warna:'b-red',
   ket:'Selisih berarti, perlu perbaikan berjadwal dan dipantau.'},
  {kode:'PENYIMPANGAN',nama:'Indikasi Penyimpangan', warna:'b-red',
   ket:'Perlu pendalaman lebih lanjut sebelum disimpulkan.'}
];
const kesimpulanDari = k => KESIMPULAN.find(x=>x.kode===k) || {nama:'—', warna:'b-grey', ket:''};

/* Usulan kategori dihitung dari angka sesi berjalan. Hanya usulan: yang
   menentukan tetap auditor, karena angka tidak selalu menceritakan konteks. */
function usulKesimpulan(){
  const rows = barisHasil();
  const nMinus = Math.abs(rows.filter(r=>r.arah==='MINUS').reduce((a,r)=>a+r.nilai,0));
  const adaFraud = state.temuan.some(t=>/fraud|penyimpangan/i.test(t.jenis));
  const out = state.temuan.reduce((a,t)=>a+Math.abs(t.out),0);
  if(adaFraud) return 'PENYIMPANGAN';
  if(nMinus > AMBANG.major || out > AMBANG.major) return 'TINDAK';
  if(nMinus > AMBANG.minor || out > AMBANG.minor) return 'PERHATIAN';
  return 'WAJAR';
}

function isiPilihanKesimpulan(){
  const usul = usulKesimpulan();
  $('capaKesimpulan').innerHTML = KESIMPULAN.map(k=>
    `<option value="${k.kode}" ${k.kode===usul?'selected':''}>${esc(k.nama)}</option>`).join('');
  jelaskanKesimpulan();
  $('capaUsul').innerHTML = `Usulan sistem berdasarkan angka sesi ini:
    <b>${esc(kesimpulanDari(usul).nama)}</b>. Ambang nilainya masih menunggu keputusan
    manajemen [MK], dan penetapan akhir tetap di tangan auditor.`;
}
function jelaskanKesimpulan(){
  const k = kesimpulanDari($('capaKesimpulan').value);
  $('capaKesKet').textContent = k.ket;
}

/* --------------------------- berita acara --------------------------- */
function renderCapa(){
  const rows=barisHasil();
  const nMinus=rows.filter(r=>r.arah==='MINUS').reduce((a,r)=>a+r.nilai,0);
  const nPlus =rows.filter(r=>r.arah==='PLUS').reduce((a,r)=>a+r.nilai,0);
  $('capaCode').textContent=state.kode;
  $('capaOutlet').textContent=state.outlet;
  $('capaHead').textContent=state.headStore || '—';
  $('capaAm').textContent=state.areaManager || '—';
  /* Head Store biasanya yang menandatangani, tetapi bisa saja yang hadir
     adalah penanggung jawab shift, jadi isian tetap dapat diubah. */
  if(!$('picName').value && state.headStore) $('picName').value = state.headStore;
  $('capaMinus').textContent=rp(Math.abs(nMinus));
  $('capaPlus').textContent=rp(Math.abs(nPlus));
  $('capaOut').textContent=rp(state.temuan.reduce((a,t)=>a+t.out,0));
  $('capaCk').textContent=ckTidakSesuai().length+' butir';
  isiPilihanKesimpulan();
  if(!$('capaDue').value){
    const d=new Date(); d.setDate(d.getDate()+3);
    $('capaDue').value=d.toISOString().slice(0,10);
  }
  siapkanTtd('signPic'); siapkanTtd('signAud');
}

const pads={};
function siapkanTtd(id){
  const c=$(id);
  if(pads[id] && c.width) return;
  const dpr=devicePixelRatio||1, w=c.clientWidth||300, h=140;
  c.width=w*dpr; c.height=h*dpr;
  const ctx=c.getContext('2d'); ctx.scale(dpr,dpr);
  ctx.lineWidth=2.2; ctx.lineCap='round'; ctx.lineJoin='round'; ctx.strokeStyle='#17151a';
  let draw=false; pads[id]={kosong:true,ctx,c};
  const pos=e=>{const r=c.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};
  c.addEventListener('pointerdown',e=>{e.preventDefault();draw=true;pads[id].kosong=false;
    c.setPointerCapture(e.pointerId);const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y)});
  c.addEventListener('pointermove',e=>{if(!draw)return;e.preventDefault();
    const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()});
  ['pointerup','pointercancel','pointerleave'].forEach(ev=>c.addEventListener(ev,()=>draw=false));
}
function clearSign(id){const p=pads[id];if(!p)return;
  p.ctx.clearRect(0,0,p.c.width,p.c.height);p.kosong=true}

function submitAudit(){
  const nama=$('picName').value.trim();
  if(!nama){toast('Isi nama PIC outlet lebih dulu');return}
  const catatan = $('capaCatatan').value.trim();
  if(!catatan){
    $('capaGalat').textContent = 'Catatan kesimpulan wajib diisi sebelum sesi dikunci.';
    $('capaCatatan').focus(); return;
  }
  $('capaGalat').textContent = '';
  if(pads.signPic?.kosong || pads.signAud?.kosong){
    toast('Kedua pihak perlu menandatangani');return}
  $('doneCode').textContent=state.kode;
  $('donePic').textContent=nama;
  $('doneTime').textContent=new Date().toLocaleString('id-ID',{dateStyle:'short',timeStyle:'short'});
  // Sesi sudah dikunci, jadi draft dibuang di sini. Bila menunggu sampai kembali
  // ke dashboard, auditor yang langsung keluar akan ditawari melanjutkan sesi
  // yang sebenarnya sudah dikirim.
  arsipkanSesi(nama, $('picRole').value.trim());
  state.sesiAktif = false; hapusDraft();
  showScreen('done');
  toast('Sesi dikunci dan dikirim untuk approval');
}

function resetSession(){
  hapusDraft();
  state.hitung.clear(); state.checklist.clear(); state.temuan=[]; state.foto=null;
  state.sesiAktif = false; state.snapshot={};
  state.headStore=''; state.areaManager='';
  const hs=$('headStore'), am=$('areaManager');
  if(hs) hs.value=''; if(am) am.value='';
  pads.signPic=null; pads.signAud=null;
  $('picName').value=''; $('picRole').value='';
  renderChecklist(); renderItemList(); updateCounters();
  showScreen('dashboard');
}

